const input = $input.first().json.body || $input.first().json;
const audio_url = input.audio_url;
const language = input.language || 'fr';

if (!audio_url) {
  throw new Error('audio_url is required');
}

if (!audio_url.match(/^https?:\/\/.+/)) {
  throw new Error('audio_url must be a valid HTTP(S) URL');
}

const job_id = `job_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;

return [{
  json: {
    job_id,
    audio_url,
    language,
    runpod_payload: {
      input: {
        job_id,
        audio_url,
        language
      }
    }
  }
}];

const runpod = $input.first().json;
const jobInfo = $('Validate & Prepare Payload').first().json;

// Handle Runpod API errors
if (!runpod.id && (runpod.statusCode || runpod.error)) {
  return [{ json: {
    error: 'Runpod API error',
    message: runpod.message || runpod.error || `Runpod returned HTTP ${runpod.statusCode || 'error'}`,
    job_id: jobInfo.job_id
  }}];
}

return [{
  json: {
    job_id: jobInfo.job_id,
    runpod_job_id: runpod.id,
    status: runpod.status,
    audio_url: jobInfo.audio_url,
    language: jobInfo.language
  }
}];
